  ('aff7bfe5-e822-19e1-e3ce-7197b9e6d614'::uuid, 'worship', 'Worship', 'Lively, heartfelt worship', 'Leading the church in worship on Sundays and at our Friday Night of Worship.', 'Our worship team leads the Sunday service and our Friday Night of Worship.', '4f45c193-e65f-85df-7678-1c6031def65a'::uuid, 'Sundays 3:00 PM · Fridays 8:00 PM', 'Chandler & Gilbert, AZ', null, array['Sunday worship','Night of Worship']::text[], '/contact?topic=worship', 1, 'published', true),
  ('8b8212f7-6195-d9cd-b4aa-9e536621dab1'::uuid, 'prayer', 'Prayer', 'A praying church', 'Night Prayer every first Friday and Morning Glory prayer at 5 AM.', 'On the first Friday of each month we gather for Night Prayer, and Morning Glory prayer meets at 5:00 AM every day except Monday and Saturday.', 'aa9b5df7-bbd7-db75-9eb3-e28d2863ba7d'::uuid, 'First Friday 9:00 PM · Morning Glory 5:00 AM', '800 W Galveston St, Chandler', null, array['Night Prayer','Morning Glory','Prayer requests']::text[], '/prayer', 2, 'published', true),
  ('6a71e112-a519-2bd8-665f-e072a8333f0c'::uuid, 'women', 'Women', 'Refresh Women', 'Women growing in faith together, and home of the Refresh Women conference.', 'In 2026 we hosted Refresh Women: we laughed, worshipped, learned and left refreshed and encouraged.', '23696574-257a-f9b8-b775-fed4212de455'::uuid, 'Announced through our events page', 'Chandler, AZ', null, array['Refresh Women conference']::text[], '/contact?topic=women', 3, 'published', false),
  ('6dea8b93-8947-887c-dd54-2055b285bd80'::uuid, 'children', 'Children', 'Sunday School', 'Our growing Sunday School shapes the next generation with God''s Word.', 'We believe our children are the next generation that will carry the Gospel to the nations, and our Sunday School is growing every week.', '445b1991-57f1-c6e4-6ab0-cced0a0d9314'::uuid, 'Sundays', '800 W Galveston St, Chandler', null, array['Sunday School']::text[], '/visit#kids', 4, 'published', true),
  ('7eaab1bc-57e7-6ac5-2b67-54acd7e208ce'::uuid, 'serve', 'Serve Team', 'Serving God and His people', 'Serving the Lord and His people is a gift we never take for granted.', 'Serving the Lord and His people is a gift we never take for granted.', 'ec854e4c-208b-d8e2-ad23-2af3f253b242'::uuid, 'Sundays', '800 W Galveston St, Chandler', null, array['Sunday serving']::text[], '/contact?topic=serve', 5, 'published', false)
