insert into public.announcements (id, title, body, link_url, link_label, is_pinned, status) values
  ('9133cae1-ce43-79eb-5709-05a3731ab1f0'::uuid, 'Celebrate our 1st Anniversary, Dec 12 & 13', 'Join us for worship and the Word.', '/events/first-anniversary-2026', 'Details', true, 'published')
insert into public.homepage_sections (key, kicker, title, body, data, sort_order, is_visible) values
  ('hero', null, null, null, '{"primaryCta":{"label":"Plan Your Visit","href":"/visit"},"secondaryCta":{"label":"Explore New Life","href":"#chapters"},"slides":[{"index":"01","label":"Faith & Worship","caption":"Worship, prayer and the Word","headline":"A place of love.\nA family of faith.","body":"A future of hope in Chandler, Arizona. Come worship with us every Sunday at 3:00 PM.","mediaId":"73543419-62b5-9629-b9c3-cd4826d929b4"},{"index":"02","label":"Community & Discipleship","caption":"Growing together as one family","headline":"Worship.\nGrow. Serve.","body":"From Sunday School to Refresh Women, we grow in Christ together and serve one another with joy.","mediaId":"bfbe240b-ad51-a269-40b6-c489cff6dd76"},{"index":"03","label":"Go & Make Disciples","caption":"Matthew 28:19","headline":"Go.\nMake disciples.","body":"Go ye therefore, and teach all nations, baptizing them in the name of the Father, and of the Son, and of the Holy Ghost. Matthew 28:19","mediaId":"7bff3621-9295-6003-0f85-d78b9931ec27"}]}'::jsonb, 1, true),
  ('stats', null, null, null, '{"items":[{"value":"3 PM","label":"Every Sunday in Chandler, AZ"},{"value":"4","label":"Weekly worship and prayer gatherings"},{"value":"5 AM","label":"Morning Glory prayer"},{"value":"1","suffix":"st","label":"Anniversary, December 2026"}]}'::jsonb, 2, true),
  ('chapters', 'Who We Are', 'Three chapters. One story of new life.', 'New Life Global is a young church in Chandler, Arizona. Here is who we are, in three chapters.', '{"chapters":[{"index":"01","title":"Faith & Worship","lead":"We worship God in a lively and heartfelt atmosphere.","body":"Every Sunday we gather to worship, to pray and to hear the Word. Our week is wrapped in prayer, from Morning Glory at 5 AM to Night Prayer on the first Friday of each month.","points":["Sunday Service · 3:00 PM","Night Prayer · first Friday","Night of Worship · Fridays"],"mediaId":"23696574-257a-f9b8-b775-fed4212de455","videoId":"tsNcq0xw4pU","cta":{"label":"Watch a message","href":"/messages"}},{"index":"02","title":"Community & Discipleship","lead":"Worship. Grow. Serve.","body":"We are a family of faith. Children grow in our Sunday School, women are refreshed and encouraged, and everyone has a place to serve the Lord and His people.","points":["Sunday School","Refresh Women","Serve Team"],"mediaId":"719dd6cb-d89c-bcb6-d119-194ffd335ff2","cta":{"label":"Find your ministry","href":"/ministries"}},{"index":"03","title":"Go & Make Disciples","lead":"Go ye therefore, and teach all nations.","body":"Matthew 28:19 is the verse at the center of our church. We pray, worship and serve with that call before us.","points":["Matthew 28:19","Night Prayer","Morning Glory"],"mediaId":"ec854e4c-208b-d8e2-ad23-2af3f253b242","cta":{"label":"Plan your visit","href":"/visit"}}]}'::jsonb, 3, true),
  ('invite-band', 'Plan your visit', 'There''s a seat saved just for you.', 'Sundays at 3:00 PM · 800 W Galveston St, Chandler, AZ', '{"cta":{"label":"Plan Your Visit","href":"/visit"}}'::jsonb, 4, true),
  ('discover', 'Discover New Life', 'Find your way in.', 'Seven pathways into the life of our church.', '{"items":[{"title":"About Us","text":"Who we are, what we believe and who leads us.","href":"/about"},{"title":"Ministries","text":"Worship, prayer, women, children and serving.","href":"/ministries"},{"title":"Messages","text":"Watch sermons from Pastor Charles.","href":"/messages"},{"title":"Events","text":"Gatherings, conferences and celebrations.","href":"/events"},{"title":"Leadership","text":"Meet our pastors.","href":"/about#leadership"},{"title":"Prayer","text":"Share a request in confidence.","href":"/prayer"},{"title":"Plan Your Visit","text":"Times, directions and what to expect.","href":"/visit"}]}'::jsonb, 5, true),
  ('pathways', 'Messages & Gatherings', 'Hear the Word. Gather with us.', 'A recent message and what''s coming up in Chandler.', '{"eventMediaId":"ae4e1b59-837d-d18c-c8e2-41171ba911d1"}'::jsonb, 6, true),
  ('ministries', 'Ministries', 'A place for everyone to belong.', null, '{}'::jsonb, 7, true),
  ('testimonies', 'Stories', 'What God is doing among us.', null, '{"items":[],"note":"Only approved testimonies with written consent."}'::jsonb, 9, false),
  ('invitation', 'Come home', 'Come and experience new life.', 'Whoever you are and wherever you''re from, you are welcome at New Life Global.', '{"mediaId":"7bff3621-9295-6003-0f85-d78b9931ec27","cta":{"label":"Plan Your Visit","href":"/visit"},"secondary":{"label":"Contact us","href":"/contact"}}'::jsonb, 10, true)
insert into public.church_content (key, label, sort_order, requires_approval, draft, published, status, review_note, published_at) values
  ('about_intro', 'About New Life Global', 1, false, '{"title":"Welcome to New Life Global","body":"A place of love, a family of faith, a future of hope. We gather every Sunday at 3:00 PM in Chandler, Arizona to worship, grow and serve together, and there is a seat saved for you."}'::jsonb, '{"title":"Welcome to New Life Global","body":"A place of love, a family of faith, a future of hope. We gather every Sunday at 3:00 PM in Chandler, Arizona to worship, grow and serve together, and there is a seat saved for you."}'::jsonb, 'published', null, now()),
  ('our_story', 'Our Story', 2, true, '{"title":"Our Story","body":""}'::jsonb, null, 'needs_confirmation', 'Awaiting the official church story from Pastor Charles.', null),
  ('mission', 'Mission', 3, true, '{"title":"Our Mission","body":""}'::jsonb, null, 'needs_confirmation', 'Awaiting the official mission statement.', null),
  ('vision', 'Vision', 4, true, '{"title":"Our Vision","body":""}'::jsonb, null, 'needs_confirmation', 'Awaiting the official vision statement.', null),
