  ('beliefs', 'What We Believe', 6, true, '{"title":"What We Believe","items":[]}'::jsonb, null, 'needs_confirmation', 'Awaiting the church''s statement of faith.', null),
  ('visit_intro', 'Plan Your Visit: introduction', 7, false, '{"title":"We saved you a seat.","body":"Whether you are new to church or looking for a church family, you are welcome at New Life Global."}'::jsonb, '{"title":"We saved you a seat.","body":"Whether you are new to church or looking for a church family, you are welcome at New Life Global."}'::jsonb, 'published', null, now()),
  ('visit_expect', 'Plan Your Visit: what to expect', 8, false, '{"title":"What to expect","body":"Our Sunday service runs from 3:00 to 5:00 PM with worship, prayer and a message from the Word. Arrive a few minutes early and someone from our team will be glad to welcome you."}'::jsonb, '{"title":"What to expect","body":"Our Sunday service runs from 3:00 to 5:00 PM with worship, prayer and a message from the Word. Arrive a few minutes early and someone from our team will be glad to welcome you."}'::jsonb, 'published', null, now()),
  ('visit_kids', 'Plan Your Visit: kids', 9, false, '{"title":"Kids","body":"We have a growing Sunday School for children. If you have questions before your visit, let us know in the form below."}'::jsonb, '{"title":"Kids","body":"We have a growing Sunday School for children. If you have questions before your visit, let us know in the form below."}'::jsonb, 'published', null, now()),
  ('give_intro', 'Giving page introduction', 10, false, '{"title":"Give","body":"Thank you for supporting the ministry of New Life Global."}'::jsonb, '{"title":"Give","body":"Thank you for supporting the ministry of New Life Global."}'::jsonb, 'published', null, now())
